      settlement: { heroTitle: 'Services d\'Établissement pour Immigrants à Toronto', heroSubtitle: 'L\'objectif de notre Programme d\'Établissement des Immigrants (ISP) est de faciliter l\'intégration sociale et économique harmonieuse des nouveaux arrivants au Canada.', ctaLabel: 'Demander du Soutien à l\'Établissement', sections: { 0: { title: 'Aperçu des Services d\'Établissement', description: 'Notre programme aide les nouveaux arrivants à s\'engager dans tous les aspects de la vie canadienne à travers des services transversaux.' }, 1: { title: 'Qui Nous Servons', description: 'Services accessibles à tous les résidents permanents, y compris les réfugiés réinstallés, jusqu\'à l\'obtention de la citoyenneté.' }, 2: { title: 'Ce que Nos Conseillers Offrent', description: 'Aide au logement, traduction, emploi, formulaires d\'immigration, accompagnement et orientation vers d\'autres services.' }, 3: { title: 'Contactez-Nous', description: 'Nouvel arrivant au Canada? Contactez-nous par courriel, téléphone ou via notre système de rendez-vous.' } } },
      ircc: { heroTitle: 'Centre de Ressources IRCC', heroSubtitle: 'Votre guide officiel des processus, formulaires et exigences de conformité d\'Immigration, Réfugiés et Citoyenneté Canada.', ctaLabel: 'Accéder aux Ressources IRCC', sections: { 0: { title: 'Formulaires IRCC et Autres Ressources', description: 'Accédez au catalogue complet des formulaires IRCC organisés par volet d\'immigration avec instructions en six langues.' }, 1: { title: 'Préparation à la Citoyenneté', description: 'Programme couvrant l\'histoire du Canada, la structure gouvernementale, les droits et responsabilités.' }, 2: { title: 'Guides de Vie Canadienne', description: 'Guides pour naviguer la vie au Canada : système de santé, droits des locataires, fiscalité, programmes provinciaux.' } } },
      'language-mentorship': { heroTitle: 'Mentorat Linguistique pour Nouveaux Arrivants', heroSubtitle: 'Aider les nouveaux arrivants à développer leur confiance, leurs compétences en communication et des liens communautaires significatifs.', ctaLabel: 'Devenir Mentor Linguistique', sections: { 0: { title: 'Bienvenue au Programme de Mentorat Linguistique', description: 'Notre programme soutient les nouveaux arrivants dans l\'amélioration de leur anglais et la connexion avec leur nouvelle communauté.' }, 1: { title: 'Notre Mission', description: 'Aider à améliorer la maîtrise de l\'anglais, les compétences professionnelles, la confiance et l\'accès à un soutien culturellement adapté.' }, 2: { title: 'Ce que le Programme Offre', description: 'Cours en présentiel, sessions en ligne, et soutien multilingue avec des mentors bénévoles.' }, 3: { title: 'Une Communauté de Mentors Solidaires', description: 'Mentors passionnés offrant conseils individuels, pratique de conversation, aide à la prononciation et soutien professionnel.' }, 4: { title: 'Pourquoi Rejoindre le Programme ?', description: 'Meilleure communication, confiance accrue, préparation à l\'emploi, liens sociaux plus forts.' } } },
      'language-services': { heroTitle: 'Services Linguistiques', heroSubtitle: 'Formation linguistique avancée, cercles de conversation en anglais et cours de citoyenneté pour les nouveaux arrivants.', ctaLabel: 'Demander des Services Linguistiques', sections: { 0: { title: 'Formation Linguistique Avancée (ELT)', description: 'Idéal pour les professionnels formés à l\'étranger n\'ayant pas pu accéder à un emploi dans leur domaine.' }, 1: { title: 'Cercle de Conversation en Anglais', description: 'Environnement sécurisé pour pratiquer l\'anglais, une fois par semaine avec 20-25 participants.' }, 2: { title: 'Cours de Citoyenneté', description: 'Préparation à l\'examen de citoyenneté canadienne : histoire, géographie, système politique, droits et responsabilités.' } } },
