      'women-empowerment': { heroTitle: 'Programmes d\'Autonomisation des Femmes', heroSubtitle: 'Le programme comprend trois domaines : violence contre les femmes, emploi et compétences de vie, et emploi spécifique aux femmes.', ctaLabel: 'Rejoindre l\'Autonomisation des Femmes', sections: { 0: { title: 'Autonomisation par les Compétences et le Plaidoyer', description: 'Activités de coaching et soutien aux victimes pour surmonter les défis passés et assumer des rôles de leadership.' }, 1: { title: 'Indépendance Économique et Compétences TI', description: 'Investissement dans le développement des compétences, l\'indépendance financière et la diversité culturelle.' }, 2: { title: 'Solutions Axées sur la Communauté', description: 'Soutien aux femmes vulnérables par des solutions communautaires renforçant l\'autonomie et la résilience.' } } },
